WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (1055::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-12-18T00:00:00+00:00'::TIMESTAMPTZ, 'ccda27833c00264156380cf77c7cb2cb02d6a766512d907666428fcd46e6d2ce'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Buen profesor, se preocupa para que se entienda la materia y es bastante comico,pero sus clases son bastante largas y no lo recomiendo que matriculen un sábado'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '55'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases largas']::TEXT[], '2025-12-17T00:00:00+00:00'::TIMESTAMPTZ, '03c746d70c91622338674ed236453958968706ec1bf5cffc6ef7cd27e0fe8b40'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'Califica para ayudar al estudiante, es bastante buena gente y se nota que le gusta lo que hace, sus clases se sienten bastante largas pero es muy bueno en lo que hace y explica bien, si usted necesita ayuda él le ayuda las veces que sean necesarias y trabaja demasiados ejemplos en clase lo que ayuda'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-17T00:00:00+00:00'::TIMESTAMPTZ, '57bf7b579e9affa94798c0d1062883fd7cfbeb418389ad0f0a28a724710244b2'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Se nota que le gusta lo que hace y eso se aprecia. Es muy buen profe en todos los sentidos, ayuda bastante, y es super buena gente y gracioso, definitivamente tomaría su clase otra vez. Como único punto negativo es que sus clases se sienten muy largas. Si usted se queda con este profe es por vago.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2025-08-05T00:00:00+00:00'::TIMESTAMPTZ, 'ca2b374f6c8bbeb90ac5d9aeddf098220117ff3a04b5f429108d8e652f152070'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Es demasiado bueno, se le nota la vocación. Súper paciente, si usted pregunta algo, le explica hasta que entienda, es demasiado flexible para consulta, él se acomoda a su horario prácticamente; además es súper empático y comprensivo. Si tiene malas bases en mate, no dude en matricular con él. Es top'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'b784e10964c2f991c64a13da7b9c602f5c215c4890a74adb6d6262bdc841c4ec'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'El profe se preocupa por el estudiante. Si llegás con malas bases, el curso se puede complicar, pero no es imposible. Al inicio cuesta entender por lo desordenado en la pizarra, pero con el tiempo se le agarra el toque. En las semanas pares siempre hay alguna actividad: tarea, quiz o Khan Academy.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases largas']::TEXT[], '2025-07-19T00:00:00+00:00'::TIMESTAMPTZ, '0923c400a6b7fea7d49d4306a1a93e6ca628035ff8dcaea5c7b1cfcc9498f803'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Muy bueno, explica super, es amable, verdaderamente se preocupa por el estudiante en las clases iba mesa por mesa a explicar y ver como hacías ejercicios para ayudarte si te esta costando les pregunta a los estudiantes que fecha les queda mas cómodo para asignar x tarea, solo hay que esforzarse'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-02-11T00:00:00+00:00'::TIMESTAMPTZ, '6d80c071a13ecc6aa266eda7b611094870d03bd0f87a5b453a7c25876a8fe6d7'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Es muy buen profesor, llevé el curso por segunda vez y con este profe logré pasarlo. Se preocupa por los estudiantes, da buenos consejos e insiste en la práctica y motivación personal. Sin duda lo volvería a llevar con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-01T00:00:00+00:00'::TIMESTAMPTZ, '0e38f3638efe8f4c7a053676b5d2e50cc99d89b232ec5e155311f20dd8f1e0e9'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Demasiado bueno y cómico, explica excelente y hace que la clase sea llevadera.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2024-12-13T00:00:00+00:00'::TIMESTAMPTZ, '7b1ef402718a3517bee81fcb5ef7b97e072a1630426ff67845abe8ae2db9f5df'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'este mae es el GOAT'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'd1840aa35b94f2c4d6124d86208b32f10b68d4a1b63c444ddd0fa9b4666d15a5'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-30T00:00:00+00:00'::TIMESTAMPTZ, '2c4efa1ff9f3f201ee455c2b6b0936e38d85dec80c65d0ca5e940543a00d0afc'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Este profe es un crack, y a pesar de que no logré pasar el curso lo volvería a llevar con él. Siempre está dispuesto a brindar apoyo y conoce la realidad de muchos estudiantes que no siempre llegan con buenas bases en mate desde sus coles. Usa plataformas como khan academy.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2024-06-27T00:00:00+00:00'::TIMESTAMPTZ, '74af8c82b7d7bc89003ae5f54cea50e50d2d5c26be6e5bda6dd4215eafc2b98d'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Muy bueno, recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '08bc27a673de7dffa715402e42187bbc26db5c15a040b8b0c5d17a0f45532e42'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'Literal es que mejor profe con el que pueden matricular, se pasa a la primera, es demasiado buena gente y se adapta a las necesidades del estudiante. Lo recomiendo 100x100'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, '13812cc57a486537597e8c8f0b77ede77e925fffbf657800de3251e5d7aaf31a'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Es un profesor que sin duda tiene vocación para lo que hace, insiste para que los estudiantes no se guarden las dudas y siempre es muy abierto a acomodar entregas a conveniencia de uno. Llevé el curso por primera vez con él y las cosas no pudieron haberme quedado más claras.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2024-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'c4a5960fe1bebf9ee83984297e29a53fa59d753bf1f6b57fc3103d7257cade97'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'Es un profesor excelente, tiene una excelente vocación y siempre busca ayudar y que el estudiante se sienta cómodo, las evaluaciones no son complicadas. Definitivamente matricule con el :D'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2024-01-28T00:00:00+00:00'::TIMESTAMPTZ, '23a78415b21ae28a0da8a60f5993ac3c1a5ef01a3d325faedfd4351963b0a2b0'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-09T00:00:00+00:00'::TIMESTAMPTZ, '701439f7d92e7ed6e53cf227ff8523feb5c6de6463d0a337d7704d9f61896360'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '60'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, '17552eef5b35de5bc7a0ac9137063c482556b6889a0635238ed42cb2010474c3'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'El mae es un locazo, super buena nota y explica muy bien, él sabe muy bien como llevarse con sus estudiantes (Da clases en colegios creo o una vara así) super recomendado, obvio como todos los cursos de la escuela, hay que ponerle mucho pero de fijo con él pasas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, '8b3dedfadbdee3dea141f4ab86fefd7596fd41bc00de7ad7cd3663b70c5c7883'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'El curso en sí tiene su dificultad, el profe se preocupa bastante porque el estudiante entienda, aunque a veces suele enredarse un poco, sin embargo, siempre esta dispuesto a ayudar.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo']::TEXT[], '2023-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'e10bf5aba347002cb6f9c7eb360d84ba3252f20184fa695ee871c62aa7891e9b'::TEXT, ARRAY[634]::BIGINT[]),
    (1055::BIGINT, 'El mejor profe que he tenido. Se preocupa demasiado por el que estudiante aprenda pero de verdad y cada clase nos motivaba para. Hace ver la materia difícil, fácil y los exámenes no eran tan difíciles si usted estudia mucho. Se nota que ama lo que hace. Sus frases son demasiado graciosas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'ff66a361936413a5be84b260e9c3998f57f6576dcb460aff5d710f10470f4dcb'::TEXT, ARRAY[2444]::BIGINT[]),
    (1055::BIGINT, 'Sin duda, uno de los mejores profes que he tenido. Se preocupa por que el estudiante aprenda e insiste mucho en que el estudiante no se quede con las dudas. Se nota que tiene vocación en lo que hace.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'a3bb771cf81758c10fd46d45d14b2053e650bef16697bc9d35b7e28ec2a47f34'::TEXT, ARRAY[2444]::BIGINT[]),
    (1055::BIGINT, 'Muy buen profe, con él he pasado la mayoria de cursos de calculo. Explica muy bien y facil la materia. Los examenes ya dependen de la catedra, pero comunmente ayuda mucho estudiante examenes viejos'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Brinda apoyo']::TEXT[], '2023-05-25T00:00:00+00:00'::TIMESTAMPTZ, '60d7a9f33b87c7c181ffd79696e5fea62b75756c43a18a1adfa64597e08f517b'::TEXT, ARRAY[634]::BIGINT[]),
    (1055::BIGINT, 'Clases entretenidas, aveces cansa un poco pero se pasa despues de un chiste. deja muchas asignaturas en khanacademy pero es solo de dedicarle tiempo a la materia para que la mula no tire a genaro. buena persona el joven'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '65'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2023-02-01T00:00:00+00:00'::TIMESTAMPTZ, '765908eac473587abefe86db6cf24579715b6e6cf4a7f88bbe6712df2eb03bfc'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Si tiene la oportunidad de matricular con este profe, aproveche. Tiene vocación para enseñar y se preocupa por el estudiante. Legalmente si promete.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-18T00:00:00+00:00'::TIMESTAMPTZ, '22e26245fc4a27e120587ec74642e12b0548c9ac05df7233c8b27887405cc984'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'Excelente profe. Se preocupa por que pasen, deja tareas extra en caso de necesitar puntos, usa Khan Academy y es muy flexible, es la mejor opción para esta clase'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2022-07-01T00:00:00+00:00'::TIMESTAMPTZ, '403fe9908a5c1dd3f23f87eba876434b84ef6f108f6e81f8512555098fb6b619'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '21d37bf1176aecb389b435958cf79e6b58b23d7eaa38f2552f0e61a64280c039'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'El profe se enreda explicando, pero es muy buena gente y ayuda a los estudiantes. También ayuda en extender fechas de las tareas.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'b2eeb608c538660d2de2a926c072ad97fb9987548cc041008a1170be3d7589fa'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'Muy buen profe, a veces se enreda explicando, pero solo es ponerle mucha atención,busca la forma que uno entienda siempre, volvería a matricular con él.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-26T00:00:00+00:00'::TIMESTAMPTZ, '21e449350f62e0de2526791c9bee23b83508e3dc114b9569fd3c33a1067c9e1d'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'El profe es buena gente y siempre trata de que el tema quede claro, aunque a veces puede enredarse. Trata de resolver todas las dudas posibles y las tareas son grupales casi todo el tiempo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2022-06-10T00:00:00+00:00'::TIMESTAMPTZ, '92f6fa227071a456bdd1f9526cd523d46102fe23b3d6440d1c841c3bc621ec70'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'El profe es genial'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-07T00:00:00+00:00'::TIMESTAMPTZ, '1494e79dab52c760c38a54baf821cd4eca1b270a60b597617461f8e9348e7cf0'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-03-01T00:00:00+00:00'::TIMESTAMPTZ, '12c9c34f3807ae32e4c4e8a90c378205745e88a9211f5ed1b7b84a7bed9846bd'::TEXT, ARRAY[634]::BIGINT[]),
    (1055::BIGINT, 'Esta mas preocupado que uno en pasar la materia, es ordenado, muy amable y accesible. Ayuda con consultas y es paciente. Utiliza Khan academy como complemento a las clases y fue muy util. Los examenes son muy muy parecidos a la materia y practica dada.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'e61af3e3eb86e6020154840c523fdb403185fef26914836c5709a418fe3ec4fc'::TEXT, ARRAY[2444]::BIGINT[]),
    (1055::BIGINT, 'el mejor profe de mate que he tenido en el tec. me hizo entender todo lo que no entendí cuando llevé el curso antes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-15T00:00:00+00:00'::TIMESTAMPTZ, '229c99a6aacf5c288edd8b1955137f2862945e15e5588c5cd0381a401d5973d8'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'El profe es una excelente persona, le encanta la participación y resuelve todas sus dudas, es flexible con las entregas y es muy empático. Nos dió repasos para todos los examenes y siempre hubo un ambiente respetuoso. Está atento al telegram por si se tienen consultas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'ee941dfbd56eb419e26bf8edeb606edac35eefde0a0e3126a60f97ebfb8f0c25'::TEXT, ARRAY[563]::BIGINT[]),
