    (1055::BIGINT, 'Excelente profesor, ayuda mucho y hace calculo más facil, con su buena práctica obviamente pero el siempre esta disponible y dispuesto a ayudar. Es un excelente profesor en muchos sentidos , con esto ayudo a que suba la nota porque alguien se hizo el gracioso'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2021-02-16T00:00:00+00:00'::TIMESTAMPTZ, '2656668059c2938bd66a73c6c07ff21d7edab70dab23ec84acdd3a27cd4c9ecb'::TEXT, ARRAY[605]::BIGINT[]),
