    (1055::BIGINT, 'Excelente profe, muy buena nota, de dice "bro" a todos mientras explica y trata a las variables de "esta prójima" el mejor de verdad, hace que la clase sea 0 aburrida y súper claro todo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, '1937917116b1645b9155196fefc229be6359399f906051f085dd615ca5e1d54d'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'Buen profe, nos dice "bro"'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'bd60ecb838371ebc89fb1511b5bf1ca2c1510b0781cfeda689d0a4457b56047d'::TEXT, ARRAY[634]::BIGINT[]),
    (1055::BIGINT, 'No entiendo por qué tiene esta calificación porque fácil, es uno de los mejores profesores que tiene la escuela de matemática por no decir que el mejor. Además las clases son súper divertidas, atiende consulta súper amable y califica justo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '9200bc396924e3da166107a451e12558cbd659b7e3e2a298567a9d937a0d5b86'::TEXT, ARRAY[563]::BIGINT[]),
