    (1055::BIGINT, 'Un excelente profe, explica de maravilla, le alcanzó para reforzar temas de cursos anteriores y cubrir todos los contenidos a la perfección. Súper recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2020-08-12T00:00:00+00:00'::TIMESTAMPTZ, '0616aecc4a1c585da122010f410119efc8ded4aaf9ba66f17f7235d66ec9d549'::TEXT, ARRAY[935]::BIGINT[]),
    (1055::BIGINT, 'Es un profesor excelente, explica muy claro y se detiene las veces que sea necesario con tal de que usted entienda , hace muchos ejercicios en clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2020-02-13T00:00:00+00:00'::TIMESTAMPTZ, '07e4af1d05944b1cfcb98b9490384441fbbc7ac36daabeb7749e9a411277d2e9'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Este voto es para normalizar la nota que este profe se merece, el tipo que seguro se cree un hacker en su casa por lograr hazaña de tan bajo calibre y digno de una persona sin principios que ni siquiera merece estar de estudiante en el tec al ponerle una nota mínima debería estar avergonzado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-02-12T00:00:00+00:00'::TIMESTAMPTZ, '843418cc967317d4441a81a228bf279ab30c97f94305fafe206221a5bde4e71c'::TEXT, ARRAY[605]::BIGINT[]),
