    (1055::BIGINT, 'Excelente profe!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-18T00:00:00+00:00'::TIMESTAMPTZ, '5bdebc751ef4398bba60d000b3bd9b63876a557fce7041a375664b1ca7c33a0a'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'Excelente profe, es una mente. Explica todo muy bien y antes de los exámenes nos pone a practicar bastante. Ayuda con el 20% de quiz y tareas. Mejor profe del semestre.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, '850dde2400b81afb18737a76195765bb5465e8d223c3fb5a55007aae3a6492b7'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'El profe es un crack, si tiene el chance de meter con él, HÁGALO.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'f666e859171b911d2cfb2060ec23a74d33f8d7805618be742bc266827b16b051'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'El curso en si no es fácil, pero el profe es demasiado crack explicando y hace que el curso se vea fácil (si usted pone de su parte y estudia verdad), tiene mucha paciencia y explica las veces que sea necesario, hace pocos quices. Si tiene la oportunidad de matricular con él no lo piense dos veces.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, '582919ff335f16179a93f4f0b655b3c3dbfd6c1d05bbff69043f4d35802c811f'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'De los mejores profes que he tenido , una excelente persona ,explica la materia super claro y bien, se enfoca en que el estudiante aprenda no solo para el examen, si no también para la vida .No dude en matricular con el Bro. No se va a arrepentir.Califica justamente y solo un quiz antes del examen.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-23T00:00:00+00:00'::TIMESTAMPTZ, '2302b7f853c3ce52f324675eeba6fc0a145142d44c247af9d5a5da1b788d94a8'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'Es muy buen profe, lo que se enseña es medio difícil, pero lo hace ver lo mas suave posible'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-10-24T00:00:00+00:00'::TIMESTAMPTZ, '2c6762e583d22569f3260bf8211e34da2c03b9d391b837bdaf0000f144a98517'::TEXT, ARRAY[1684]::BIGINT[]),
