    (1055::BIGINT, 'Resuelve dudas por el grupo de Whatsapp, siempre está interesado en que el estudiante aprenda. Prefiere dejar tareas antes que hacer quices. Tiende a salir 10min más tarde (por aquello). Chistoso y súper Pura Vida. Califica suave!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'c13a17e17e730961a7d18e6f002b8c7ef01b427f6181c385216d7667396c7ab5'::TEXT, ARRAY[634]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, '6d934adcf41c76dbabaeaf67605aa51c6c81ffe42f6209d7ab6122a927a09c2f'::TEXT, ARRAY[1684]::BIGINT[]),
    (1055::BIGINT, 'El profe se interesa mucho por el grupo y busca que siempre quede todo claro, da la confianza para preguntar las veces que sea necesario. Excelente profe, matricularía con el de nuevo sin pensarlo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2019-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'c7bdb635e0150f552f13eeb51c2ed18c80260f809e5d27766896d53ddd778a46'::TEXT, ARRAY[634]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, '7547239f0250926bb1b8c0a48e4b595118944cbdc3b450abdef9e5306d23f7b0'::TEXT, ARRAY[935]::BIGINT[]),
    (1055::BIGINT, 'Es un muy buen profe, realmente se interesa en el desarrollo del estudiante, prefiere que uno analice los ejercicios y los resuelva en lugar de memorizar. Explica cuantas veces lo necesite y cuando puede se queda después de clase a aclarar dudas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2019-05-30T00:00:00+00:00'::TIMESTAMPTZ, 'dc51c2bf80eb57e969fa5a77711ee6c718eb392ddcdb5e9e373d36d6f1fdd7fb'::TEXT, ARRAY[634]::BIGINT[]),
    (1055::BIGINT, 'Excelente profesor, de los mejores profesores que se puede topar uno al principio de la carrera, le dedica tiempo al curso y a los estudiantes, hace mucha practica y ejemplos para que todo quede claro'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-31T00:00:00+00:00'::TIMESTAMPTZ, '4f3a90dcd1c708e70bda3cefbd2755f85223c7f4a6ec6bb9ca9a31a638ac8a07'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Es el mejor profesor que he tenido Increible el apoyo que brinda Super súper recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-01-24T00:00:00+00:00'::TIMESTAMPTZ, '6a0acca504f03f7f2dd71bfc4fe131c6f709017459b5e142648a9c855729556f'::TEXT, ARRAY[2444]::BIGINT[]),
    (1055::BIGINT, 'El profe Marvin Abarca no es sólo un profe de matemática, es un profe que le enseña a uno de la vida y que muchas veces los retos de la vida no son tan complicados como los pintan. Siempre recordaré una frase que utilizó que tenemos que ahuyentar nuestros fantasmas para crecer personalmente.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-12T00:00:00+00:00'::TIMESTAMPTZ, '36d2776dc5c1fcaf2a4f1b64dc0bccd771499e13e05f7743f3db81357d788ca0'::TEXT, ARRAY[2444]::BIGINT[]),
    (1055::BIGINT, 'El bro, es un excelente profesor, se preocupa por que el estudiante de verdad entienda la materia y gane el curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2018-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'c2d8dc213b26a0e897990a9562607ec3bb80f3573ab06ec5c19aed313d5e38a6'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Muy buen profe, hace ver todo más fácil!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2018-08-18T00:00:00+00:00'::TIMESTAMPTZ, 'b1695c168d346652b98576f26cc24b67bbadbffd846ee139cbf47196ecfdb914'::TEXT, ARRAY[1864]::BIGINT[]),
    (1055::BIGINT, 'Un EXCELENTE profesor. Altamente recomendado, fácilmente de los mejores profesores del TEC.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2018-07-16T00:00:00+00:00'::TIMESTAMPTZ, '190d004ef54951998e8ab8520c1d011bda538d7e09dc66a6ada5b530a90789cc'::TEXT, ARRAY[1864]::BIGINT[]),
    (1055::BIGINT, 'Muy buen profe, te explica cuanto sea necesario, es muy pura vida, las clases no son aburridas y los examenes son lo que se ve en las practicas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'd81b9236b0291f391406f529dd5068848562344b7b4670f536656c37d6e42415'::TEXT, ARRAY[1864]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'f98beffb9861284b7bd3ef0b2b852cc758fd0f84c042ef83df143caaf61860e0'::TEXT, ARRAY[1034]::BIGINT[]),
    (1055::BIGINT, 'Se esmera en que el estudiante entienda la materia. Pone muchos ejemplos de todos los temas. Mantiene un contacto cercano con el estudiante. Casi no hace quices y, si los hace, avisa con tiempo. Es super buena gente pero a veces llega tarde.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-15T00:00:00+00:00'::TIMESTAMPTZ, '9f57fcde92ef4e85eb4be908724f11099caf869a34c2eb631a5922c4f3836080'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'd216a404f82568aa595df92afc622f73de986b7ec11c9776ad896860fda299db'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'Excelente profesor de matemáticas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-01-17T00:00:00+00:00'::TIMESTAMPTZ, 'c834a2f0ccc1895b6422520986ea446e8e4d23971e4d56a217b09394be468893'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Explica cuántas veces sea necesario, es muy bueno explicando y se preocupa por aclarar dudas fuera de horario si es necesario.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-06T00:00:00+00:00'::TIMESTAMPTZ, '7734c57b9cbdb17d10c38832d17356c14f351ccc8b47cbfb5d4e5d9ce4bb154f'::TEXT, ARRAY[2920]::BIGINT[]),
    (1055::BIGINT, 'Explica demasiado claro, atiende las dudas cuantas veces sea necesario, se interesa muchísimo por el aprendizaje de los estudiantes y súper pura vida como persona, lo recomiendo!'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, '9cee4c1e10062236cc124e5b8dfd556342616cb2e9fae30b856f476ec0d6ab1a'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, '9400b6083d558402827d9ab0e564d01fafa012d52f1c6d336ccaf8a4325670be'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'Como es normal, un curso de cálculo es complicado. Sin embargo este señor lo hace ver todo claro, su manera de dar la clase es entretenida y nunca deja que un estudiante no hable. Acepta reclamos y es una teja como persona.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-25T00:00:00+00:00'::TIMESTAMPTZ, '89c8ee4e242ae3cb43ce41bca3734f724c9211227b7bfb785e7a87f8aeeee77f'::TEXT, ARRAY[2920]::BIGINT[]),
    (1055::BIGINT, 'simplemente EXCELENTE, deja todo super claro y sus clases son super entretenidas, es demasiado buena nota y aclara las dudas super bien. Volveria a matricular con el 1000 veces mas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'e972d97940e2fff9ec2ec5d771ec9333683675e9b5353c748d66beaad91eb5a3'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'eaea37109eb20b75def489a1f1d17aaa0cb35759b049e04efb7c1fcc90c8ee0a'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-20T00:00:00+00:00'::TIMESTAMPTZ, '6fbd3a607df0e83cb7a75907a0f5c77dd4e95762ed9fc670171ffb86401c32f5'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'Vaya a clases, ponga atención y pasa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'e4ad07ea8f9c89084a55207725f16ba5009b40fcfc9ba9c1fbf1ebfc4027e408'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'Lo más lindo!! Meta con el 10000%!! Tiene la paciencia del mundo entero y explica mil veces si es necesario, muy tranquilo y explica SUPER bien!! Si uno pone atención y práctica el evacua todas sus dudas y se vuelve un curso muy sencillo! Super super recomendado, lo más bueno que hay es él :) !!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '071e93d449421051592b0fdef7963855246a059169f81175232c252236ae7c6c'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'f0be33b2ced1a4ddf0653518bd8a38b0b27e0b545b5119bb014b1278bf7523d9'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Es muy divertido, explica bien aunque le hace falta ver más teoria se enfoca en lo practico. Excelente profe!'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2017-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'eba4732493116b08738f58e2af9ed8a53fc087402ae89d7c5e7fc10e6485caae'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-04-24T00:00:00+00:00'::TIMESTAMPTZ, '1ef0d60fc6375b1392ff2b92799f76aaa47d5ca6f7632709c886b80504f4458a'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'El profe más teja! Es súper amable y explica cuántas veces se le pida. De esos profes a los que les interesa que el estudiante aprenda. No dude en llevar un curso con el!!!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-03-09T00:00:00+00:00'::TIMESTAMPTZ, '9c73402058dd5b24d444a2cbb58d9469c03a6329484f9052114c7df829f78763'::TEXT, ARRAY[2444, 605, 634]::BIGINT[]),
    (1055::BIGINT, 'Muy buen profe. A veces pone puntos extra en los exámenes. Califica justo, no regala nada. Es atento y explica bien, con mucha paciencia.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'ff1e05bf2ac06c3cc49bab7a49de6413f31767427f98f46bb7dede2bcdbccd94'::TEXT, ARRAY[2444, 605, 634]::BIGINT[]),
    (1055::BIGINT, 'El mejor profe que pueda existir, simplemente es excelente! Si tiene la oportunidad de meter el curso con él, no lo dude!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2017-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'c2877046ec9680f4204221531d0578ed4e18f37e3920513ebcf735393b4ae600'::TEXT, ARRAY[2439]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-29T00:00:00+00:00'::TIMESTAMPTZ, '6ebe85bfaa9d5c191de269d1e1301f1e64942cc3da573dd61b2efa74d53e2290'::TEXT, ARRAY[2444, 605, 634]::BIGINT[]),
    (1055::BIGINT, 'Este mae hace que usted ame la matemática, de los mejores, califica justo, se interesa mucho por el estudiante, las clases se disfrutan demasiado, quices medio difíciles, deja tareas, en consulta es muy bueno y atento.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-11T00:00:00+00:00'::TIMESTAMPTZ, '9d8de13f73975c3ba177678f50a30330810a435095f8c0f6ebb9f9aa584d71f8'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'Excelente profesor, se interesa por los alumnos y lo ayuda a uno a entender. Califica de manera justa y dura, pero no es problema porque en clase explica cómo evalúa. Tiene mucha pasión por las matemáticas y explica cualquier tema que uno le pregunte, da tips para todo. Recomendadísimo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-14T00:00:00+00:00'::TIMESTAMPTZ, 'd087cf78575a2c8fcb01046b062dcb702ae725a615f503ba9ecfb0b7c16ca711'::TEXT, ARRAY[2920]::BIGINT[]),
    (1055::BIGINT, 'Muy buen profe, sus explicaciones son muy buenas, muy simpatico incluso hizo un grupo en whatsapp para aclarar cualquier duda que tengan los estudiantes a lo largo de la semana, lo recomiendo, tambien les doy un consejo, estudien bastante porq lo mas importante es practicar y preguntar al profe'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'cd8d9ebaf6e1a1bf18d316a6d2ac5da53c12e60c404a3733751f58a26d78b399'::TEXT, ARRAY[2920]::BIGINT[]),
    (1055::BIGINT, 'Genial. Excelente profesor.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'ff1be973933da4a7f9b8551a21f851dc1272bd574d3da1faf6203c2889d0aa8b'::TEXT, ARRAY[2920]::BIGINT[]),
    (1055::BIGINT, 'El profe es excelente explicando, no exige demasiado durante el curso y lo prepara muy bien a uno para los examenes, muy recomendado'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-30T00:00:00+00:00'::TIMESTAMPTZ, '5bd09458cb48b6af90d9148c2b480130b2d5fa0b647ca42253cbf9371531b4d2'::TEXT, ARRAY[2444, 605, 634]::BIGINT[]),
    (1055::BIGINT, 'Excelente profesor! Se nota que ama lo que lo que hace. No califica muy duro y siempre esta atento a las dudas, lo recomiendo por qué de verdad se aprende'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2016-09-14T00:00:00+00:00'::TIMESTAMPTZ, '6fd7e1f46cb9a5824735cde4115bf8abfc06c3bea91d34e792fac817aeee7b88'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, '98cedd34289f330bb5a4dfcbb0d0c3601c4a19ca9dce9cb8a32762e5073d0a48'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '252ca51f100dc8aaad22734c38abb426dd9362ade54b8f0f41bf8b4db27e8172'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Le importa mucho que uno entienda la materia. Deja unas cuantas tareas y muchos exámenes viejos para practicar en clase. Hace ver la materia del curso fácil.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '8e20ef400159384ca3da1c18270d2570c589f2bbd10ea8e6f74ab21ac565a3e9'::TEXT, ARRAY[1041]::BIGINT[]),
