    (1055::BIGINT, 'Excelente profesor. Se preocupa por el estudiante y el bienestar del mismo. Hace quices y tareas fáciles. Muchos exámenes viejos de práctica. Explica bastante bien y en algunas ocasiones hace las clases cómicas. 100% recomendado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'bbefb836f5d6e053163a2861ceb0992fd0d2bb6180e787138dd69e51672cc72c'::TEXT, ARRAY[1041]::BIGINT[]),
