    (1055::BIGINT, 'Excelente profesor. Explica muy bien, siempre se preocupa de que uno entienda, y es muy buena persona. Por ahora es el mejor profesor que he tenido de matemáticas en el TEC.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-30T00:00:00+00:00'::TIMESTAMPTZ, '37904986780c0e5fbf76e5ec9b658aa24add7efcb0ed743f8c1275a69a6527c1'::TEXT, ARRAY[2920]::BIGINT[]),
    (1055::BIGINT, 'Excelente profesor. Explica muy bien, es solo de prestarle la suficiente atención y practicar. Recomendadisimo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, '626da7270e2d46a92d7584583ce2ccd61fa95a852fbf0f650f26478c1254310d'::TEXT, ARRAY[605]::BIGINT[]),
