    (1055::BIGINT, 'Excelente profesor. Es un poco desordenado en las pizarras. Explica muy bien, todo queda claro. Intenta que haya un clima de confianza. Repite las veces que sea necesario. Califica bien, y acepta reclamos a veces hasta en lápiz. Ayuda mucho en el porcentaje de tareas y quices. Recomendado siempre'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-21T00:00:00+00:00'::TIMESTAMPTZ, '0f29dd1d2647aad22b39841546443a172231de3314db7fc661f9bd454b1a1019'::TEXT, ARRAY[605]::BIGINT[]),
