    (1055::BIGINT, 'Demasiado bueno!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '029a20393d4483822dd9a2014cada39cf3298522ce5fdafbccfdc0931b057c52'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Excelente profesor y persona, ayuda bastante...'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '8cd6a667a1a454ea0553b106394efb334a2b5a6588584703de88bbdec3802bc4'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '1d3df42f9cd72718508b80dd2227ea202e469e9fb9e6b95f42a2da83b50d266f'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '5e549b3508ff4bb5d8b7e1f0cc7acb1733cec0980d429f7647163543d32ef391'::TEXT, ARRAY[2444, 605, 634]::BIGINT[]),
    (1055::BIGINT, 'Excelente profesor y persona'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'f3816bbac0d98cf2302242bba9b374e6aaab1184dbc447812404d61ca56c44f6'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'Muy buen profe, se interesa por enseñar y ayuda tanto en clase como en la oficina'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-17T00:00:00+00:00'::TIMESTAMPTZ, '4c21799a88d5f76f3c19ebc10b9f6c12b4e3b2664bdc2ca50819e930a3b502c8'::TEXT, ARRAY[2439]::BIGINT[]),
    (1055::BIGINT, 'El profe es muy bueno, se preocupa por que el estudiante se interese por los temas y lo prepara bien para el examen. Es muy vacilón'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2025-10-23T00:00:00+00:00'::TIMESTAMPTZ, '50f9af9151cb503f6da3113af679698c6716d27e67a295f76da3b676385308fe'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'se esmera porque los estudiantes comprendan la materia y no solo memoricen. Si uno va a consulta el profesor le explicará todas las veces que usted requiera. Los quices son de dificultad media sin embargo suele hacer actividades en khan academy para levantar notas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'ea3f5e86691ba18ebb41f3652b6482089e1b87da092a54e3bda783b7da9914d8'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'El curso en sí tiene su dificultad, el profe se preocupa bastante porque el estudiante entienda, aunque a veces suele enredarse un poco, sin embargo, siempre esta dispuesto a ayudar.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo']::TEXT[], '2023-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'e10bf5aba347002cb6f9c7eb360d84ba3252f20184fa695ee871c62aa7891e9b'::TEXT, ARRAY[634]::BIGINT[]),
    (1055::BIGINT, 'De lo mejor para calculo, es muy consciente de la carga de los estudiantes y esta dispuesto a ayudar. Las clases antes del examen las agarra para practicar y se queda mas tiempo si los estudiantes así lo quieren.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-18T00:00:00+00:00'::TIMESTAMPTZ, '6644fc8cb984085b15e28af8839f54e58b57ad9e69699d1b93811d943dec2f77'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'Excelente, hasta para los exámenes dos tres días antes fuera de horario da tutoria para aclarar todas las dudas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '1fdbf92da93b1d82beb699c13c7ca1ed6ed0f23ce5054248de20378270f239bc'::TEXT, ARRAY[563]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-16T00:00:00+00:00'::TIMESTAMPTZ, '0f1cf9a40e66e3059c24f06ee0555e97fd39000786d0b0dca099fcd7f3803839'::TEXT, ARRAY[634]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, '2760352948ae22a90f48e668a768c14d2ffd19c5a377009a289ff46fd1099a51'::TEXT, ARRAY[634]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '445bae7b3a5519f659d67f29687b9f7d0f8a112e67ce09cd16a6a31be65b2a07'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'El curso en si no es fácil, pero el profe es demasiado crack explicando y hace que el curso se vea fácil (si usted pone de su parte y estudia verdad), tiene mucha paciencia y explica las veces que sea necesario, hace pocos quices. Si tiene la oportunidad de matricular con él no lo piense dos veces.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, '6bf25d88ff4000a16e5667e4b74be1cac44001bf9a24c34c916516a6ee27cf3c'::TEXT, ARRAY[605]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '40'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Clases largas']::TEXT[], '2019-06-28T00:00:00+00:00'::TIMESTAMPTZ, '292fcf5b58576757fdb2055a3e73fd522afd4a9fa563a4fdf663dd5307aeb77b'::TEXT, ARRAY[2444, 605, 634]::BIGINT[]),
    (1055::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-05-30T00:00:00+00:00'::TIMESTAMPTZ, 'a19e779f68418d19a01c26da5ec0bf088463c107bc2378bc096c48aa2f8856fe'::TEXT, ARRAY[634]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
